import math

def is_power_of_two(n):
    """Checks if n is a power of two and n >= 2."""
    if n <= 1:
        return False
    return (n & (n - 1) == 0)

solutions = []

# W2's Modulo 3 Constraints:
# 1. x cannot be congruent to 1 mod 3.
# 2. If x = 0 mod 3, k must be even.
# 3. If x = 2 mod 3 and n is even, k must be even.
# 4. If x = 2 mod 3 and n is odd, k must be odd.

for n in range(2, 9):  # n from 2 up to 8
    for x in range(n + 1, 26):  # x from n+1 up to 25

        # --- Step 1: Apply Modulo 3 Constraints ---
        x_mod_3 = x % 3

        if x_mod_3 == 1:
            # Case 2: x = 1 mod 3. Impossible by W2 analysis.
            continue

        # Calculate the LHS expression needed to check for power of 2
        target = x**n + x - 2

        if target <= 0:
            # Should not happen for x >= 2, n >= 2
            continue

        # --- Step 2: Check if target is a power of 2 ---
        if is_power_of_two(target):
            # target = 2^k, so k = log2(target)
            k = int(math.log2(target))

            # --- Step 3: Check constraints on k parity based on x and n ---

            is_valid = True

            if x_mod_3 == 0:
                # Case 1: x = 0 mod 3. k must be even.
                if k % 2 != 0:
                    is_valid = False

            elif x_mod_3 == 2:
                # Case 3: x = 2 mod 3
                if n % 2 == 0:
                    # n is even. k must be even.
                    if k % 2 != 0:
                        is_valid = False
                else:
                    # n is odd. k must be odd.
                    if k % 2 != 1:
                        is_valid = False

            if is_valid:
                solutions.append((x, n, k))

print("Found solutions (x, n, k):")
for sol in solutions:
    print(sol)

print("\nTotal solutions found:", len(solutions))

