def check_power_diff(x, n):
    try:
        target = x**n + x - 2
        if target <= 0:
            return None, "Target non-positive"
        k = round(math.log2(target))
        if 2**k == target:
            return k, "Exact solution found"
        else:
            return None, f"Not a power of 2. Target: {target}, Power of 2 check failed."
    except OverflowError:
        return None, "Overflow occurred."

